def paired(rows, cond, t, rate, a, b):
    by = {(r['seed'], r['rule']): r for r in rows if r['condition'] == cond and r['noise_type'] == t and r['noise_rate'] == rate}
    seeds = sorted({s for s, _ in by if (s, a) in by and (s, b) in by})
    bb = sum(by[s, a]['success'] and not by[s, b]['success'] for s in seeds)
    cc = sum(by[s, b]['success'] and not by[s, a]['success'] for s in seeds)
    return {'condition': cond, 'noise_type': t, 'noise_rate': rate, 'a': a, 'b': b, 'pairs': len(seeds),
            'a_only_success': bb, 'b_only_success': cc,
            'risk_difference_a_minus_b': (sum(by[s, a]['success'] for s in seeds)-sum(by[s, b]['success'] for s in seeds))/len(seeds) if seeds else None,
            'p_exact_mcnemar': mcnemar_exact(bb, cc)}


def paired_count(rows, cond, t, rate, a, b, key):
    """Two-sided exact sign test on per-seed differences of a count outcome (ties dropped)."""
    by = {(r['seed'], r['rule']): r for r in rows if r['condition'] == cond and r['noise_type'] == t and r['noise_rate'] == rate}
    seeds = sorted({s for s, _ in by if (s, a) in by and (s, b) in by})
    d = [by[s, a][key]-by[s, b][key] for s in seeds]
    pos = sum(x > 0 for x in d); neg = sum(x < 0 for x in d)
    return {'condition': cond, 'noise_type': t, 'noise_rate': rate, 'a': a, 'b': b, 'outcome': key, 'pairs': len(seeds),
            'a_greater': pos, 'b_greater': neg, 'ties': len(d)-pos-neg,
            'mean_difference_a_minus_b': sum(d)/len(d) if d else None, 'p_exact_sign_test': mcnemar_exact(pos, neg)}


def bootstrap_diff(rows, cond, t, rate, a, b, key, reps=2000, seed=20261029):
    by = {(r['seed'], r['rule']): r for r in rows if r['condition'] == cond and r['noise_type'] == t and r['noise_rate'] == rate}
    seeds = sorted({s for s, _ in by if (s, a) in by and (s, b) in by})
    if not seeds: return None
    d = [by[s, a][key]-by[s, b][key] for s in seeds]; rng = random.Random(seed); boots = []
    for _ in range(reps):
        sample = [d[rng.randrange(len(d))] for _ in d]; boots.append(sum(sample)/len(sample))
    boots.sort()
    return {'mean': sum(d)/len(d), 'ci95': [boots[int(.025*reps)], boots[int(.975*reps)-1]], 'clusters': len(seeds)}


