def checkpoint(run, segment, exec_dir=EXEC):
    manifest, rows, checks = collect(run)
    out = {'segment': segment, 'utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'sealed': len(rows),
           'planned': len(manifest['units']), 'audit_all_passed': all(c['passed'] for c in checks),
           'failed_checks': [c for c in checks if not c['passed']],
           'infrastructure_errors': sum(r['infrastructure_error'] for r in rows),
           'infrastructure_exclusions': sum(r['infrastructure_excluded'] for r in rows),
           'action_timeouts': sum(r['action_timeout'] for r in rows),
           'trials_with_fault_deferral': sum(r['fault_deferrals'] > 0 for r in rows),
           'trials_with_workspace_cancellation': sum(r['workspace_cancellations'] > 0 for r in rows),
           'note': 'Administrative checkpoint: counts only, no inference; outcomes never affect continuation.'}
    write(Path(exec_dir)/segment/'checkpoint.json', out); write_csv(Path(exec_dir)/segment/'checkpoint_trials.csv', rows)
    print(json.dumps(out, ensure_ascii=False)); return out


